 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.init 	= function() {

	try {
		// 공통 기능 설정
		_setCommon();

		// 공통 HTML 요소 추가
		_setCommonElement();

		// 시스템별 공통 기능 설정
