		// anySign 시스템별 공통 기능 설정
		_setCommonAnySign();

		// 모달 설정
		_setCommonModal();

		// 전용브라우져 초기 설정
		gcm.initWbrowser();

		// window message 설정 (외부 솔루션 연동용)
		gcm.postmessage.init();
	} catch(ex) {
		console.log(ex);
	}

	/**
	 * 함수명 	: _setCommon
	 * 함수설명	: 공통 기능 설정 (내부함수)
	 * 				- onpageunoload 이벤트 대신 처리를 위해 blank 페이지를 추가
	 * 				- IME 모드 설정 (로그인 : 영어, 다른페이지 : 한글)
	 * 				- 포커스, GridView 속성 기본 설정
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _setCommon() {

		//=======================================================
		// FloatingLayer 컴포넌트 모달 속성 추가
		//=======================================================
		com.comp.setFloating(mf);

		// onpageunoload 이벤트 비정상으로 blank 페이지를 추가
		com.page.setUnloadBlankPage(mf);

		//====================================================================
		// ime-mode 설정 (IM10 시스템 : 팝업창은 한글 / 로그인 창은 영어)
		//  - IM10 : Im10ComLogin
		//	- SM30 : Sm30UserSptSysLogin
		//	- EM40 : Em40R0Login
		//====================================================================
		var engFile = ['Im10ComLogin', 'Sm30UserSptSysLogin', 'Em40R0Login'];
		if (window.name) {
			com.page.setImeMode('Korean');
		} else {
			var urlParam	= WebSquareExternal.w2xPath;

			if (com.util.isEmpty(urlParam)) {
				com.page.setImeMode('Korean');
			} else {
				var fileNm 		= urlParam.match(/[^\/](\w|[가-힣])+(?=\.)/)[0];
				var findEngFile	= engFile.filter(function(item) {return item == fileNm});

				if (findEngFile.length == 0) {
					com.page.setImeMode('Korean');
				} else {
					com.page.setImeMode('English');
				}
			}
		}

		// 포커스 정보 초기설정 (IM10 시스템)
		window.focusInfo		= {};

		// GridView 기본 visibleRowNum, pageListSize 로드
		gcm.GRID_VISIBLE_ROWNUM = com.util.getPropertyIntValue("egov.common.pagenationpageUnit");
		gcm.PAGE_LIST_SIZE 		= com.util.getPropertyIntValue("egov.common.pagenationpageSize");


		//=======================================================
		// AnySign 취소 시 호출할 콜백 함수 등록
		//=======================================================
		window.SignCancel_callback = function() {

			var funcInfo	= gcm.ANYSIGN_CANCEL_FUNC_INFO;
			if (com.util.isNotEmpty(funcInfo.funcName)) {
				var execFn		= WebSquare.util.getGlobalFunction(funcInfo.funcName, funcInfo.scopeId);

				if (execFn) execFn();
			}
		};


		//=======================================================
		// Split show/hide에 따른 패널 넓이 refresh 처리
		//=======================================================
		gcm.SPLIT_OBSERVER = new IntersectionObserver(function(entries, observer) {

			for (var i = 0 ; i < entries.length ; i ++) {
				var splitEl	= entries[i].target;

				console.log('SPLIT DIV WIDTH : ' + splitEl.offsetWidth);

				if (splitEl.offsetWidth != 0) {
					splitEl.splitObj.refresh();
				}
			}
		});
	}


	/**
	 * 함수명 	: _setCommonElement
	 * 함수설명	: 공통 HTML 요소 추가 (내부함수)
	 * 				- excelUploadFrame__ : 엑셀업로드 용 iFrame
	 * 				- uploadFileForm__ : 파일업로드 용 Form
	 * 				- fileUploadFrame__ : 파일업로드 용 iFrame
	 * 				- 포커스, GridView 속성 기본 설정
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _setCommonElement() {
		//============================================================================
		// 공통 HTML 요소 추가
		//============================================================================
		// 엑셀 업로드 target IFrame 
		var excelIFrame	= '<div><iframe name="excelUploadFrame__" style="display:none;" title="빈프레임"></iframe></div>';
		$('body').append(excelIFrame);

		// 파일 업로드 Form
		var fileForm	= '<form name="uploadFileForm__" method="post" enctype="multipart/form-data" target="fileUploadFrame__" accept-charset="euc-kr" style="display:none;">'
		$('body').append(fileForm);

		// 파일 업로드 taget IFrame
		var fileIFrame	= $('<div style="display:none;"><iframe name="fileUploadFrame__" title="빈프레임"></iframe></div>');
		$('body').append(fileIFrame);

		// 파일 업로드 taget IFrame
		var ozIFrame	= $('<div style="display:none;"><form name="ozReportForm__"></form><iframe name="ozReportFrame__" title="빈프레임"></iframe></div>');
		$('body').append(ozIFrame);

		// textArea byte check (onInput 시 한글완성형의 경우 IME모드 버퍼를 지우기 위한 용동)
		$('body').append("<input type='text' id='__IME_HIDDEN__' style='width:0px;height:0px;border:0px;padding:0;position:absolute' title='IME_HIDDEN'>");

		//==========================================================================
		// 파일 업로드 완료 시 이벤트 ( fileUploadFrame__)
		//	- 서비스에서 처리한 결과를 iFrame의 text를 파싱하여 성공여부 콜백
		//==========================================================================
		fileIFrame.find('iframe')[0].addEventListener('load', function(e) {

			// 웹스퀘어 processMessage 숨기기
			WebSquare.layer.hideProcessMessage();

			try {
				// 서비스 결과 메시지 파싱 (dataTxt)
				//	- '' : 성공 콜백
				//	- !'' : JSON 파싱
				//		- 에러 :  gcm.sbm._callbackSubmitFunction 호출 ({responseStatusCode : '500'}, 콜백함수)
				//		- 성공 : gcm.sbm._callbackSubmitFunction 호출 (JSON 데이터, 콜백함수)
				var dataTxt	= this.contentDocument.body.innerText;

				if (dataTxt == '' ) {
					if (gcm.CB_FUNCTION_FILEUPLOAD.success) gcm.CB_FUNCTION_FILEUPLOAD.success(data);
				} else {
					var data 		= JSON.parse(this.contentDocument.body.innerText);
					var resData		= {responseJSON : data};
					var tempObj 	= {
						exceptionCallbackFn : (gcm.CB_FUNCTION_FILEUPLOAD.fail) ? gcm.CB_FUNCTION_FILEUPLOAD.fail : null
					};

					// 공통 submission 결과 함수 호출
					//	- 서비스 에러 메시지가 있을 경우 공통 submission에서 띄움
					//	- 콜백함수 호출
					if (gcm.sbm._callbackSubmitFunction(resData, tempObj)) {
						if (gcm.CB_FUNCTION_FILEUPLOAD.success) gcm.CB_FUNCTION_FILEUPLOAD.success(data);
					}
				}
			} catch(e) {
				var resData = {responseStatusCode : '500'};
				var tempObj	= {execptionCallbackFn : (gcm.CB_FUNCTION_FILEUPLOAD.fail) ? gcm.CB_FUNCTION_FILEUPLOAD.fail : null};

				// 공통 submission 결과 함수 호출
				gcm.sbm._callbackSubmitFunction (resData, tempObj);
			}
		});
	}

