/**
 * 함수명 	: gcm.initWbrowser
 * 함수설명	: 전용브라우져 초기 설정
 * 파라미터	: N/A
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.initWbrowser 	= function() {

	//====================================================================
	// 전용브라우져 제공 기능
	//	- 종료 시 메시지 처리 (IM10
	//	- 스크린 정보 저장
	//	- 브라우져 팝업 창 모달 활성화 처리
	//====================================================================
	if (window.wbrowser) {
		//===================================================================
		// 마우스 앞뒤 버튼 막기 (history.back)
		//===================================================================
		com.comp.addHtmlEvent(window, 'mouseup', function(e) {
		   if (e.button == 3 || e.button == 4) {
			   com.win.stopEvent(e);
		   }
	    }, true);

		//===================================================================
		// 브라우져 종료 메시지
		//===================================================================
		var mainWindow	= gcm.win.getMainWindow();
		if (window == mainWindow) {
			window.wbrowser.setCloseMessageBox(true, document.title, '종료 하시겠습니까?');
		}

		//========================================================================
		// IM10 시스템
		//  - 해당 페이지가 로그인 페이지인지 포탈메인인지 확인 후 메시지 노출
		//========================================================================
		if (gcm.SYS_ID == 'IM10' && com.util.isEmpty(window.name)) {

			// 각 시스템 초기 세션 생성
			//if (mf.scope.wdc_main) gcm.session.initSystem();

			// 종료 버튼 시 메시지 처리
			window.wbrowser.onbeforeunload = function () {

				if (mf.scope.wdc_main) {

					// 메인 페이지에서 'X' 버튼 클릭 시
					// 로그아웃 후 윈도우 종료

					// 팝업창이나 메시지창이 열려 있는 경우는 메인창이 닫히지 않도록 한다.
					if ($p.getPopupList().length > 0 || com.message.isOpenMessage()) {
						var msgOption = {
					         msgType     : 'info',
					         msgTitle    : 'egov.message.title.web.com.info',
					         msgCode     : 'im10.message.info.web.com.0030',
					    };

						com.message.openMessage(msgOption);

						return false;
					}

					var msgOption = {
						msgType     : 'question_yesno',
			            msgTitle    : 'egov.message.title.web.com.info',
			            msgCode     : 'im10.message.info.web.com.0027',
			            closeFocusID : 'NO',
			        };

			        com.message.openMessage(msgOption, function(data) {
			        	if (data.btnType == 'yes') {
			        		mf.scope.wfm_header.scope.scwin.logout().then(function(isClose) {
			        			if (isClose == true) {
			        				window.close();
			        			}
			        		});
			        	}
			        });	
				} else {
					// 로그아웃 페이지에서 'X' 버튼 클릭 시
					var msgOption = {
						msgType     : 'question_yesno',
			            msgTitle    : 'egov.message.title.web.com.info',
			            msgCode     : 'im10.message.info.web.com.0027',
			            closeFocusID : 'NO',
			        };

			        com.message.openMessage(msgOption, function(data) {
			        	if (data.btnType == 'yes') {
			        		window.close();
			        	}
			        });
				} 
				return false;
			};
		} else if (gcm.SYS_ID == 'SM30' || gcm.SYS_ID == 'PM10') {
			setTimeout(function() {
				wbrowser.setControlBoxButton('maximize', true);
				wbrowser.setControlBoxButton('close', true);
			}, 100);
		}

		// 스크린 정보 저장
		_setScreenInfo();

		// 하위 브라우져 모달 팝업 창 활성화 처리
		_setPopupActive();
	}

	/**
	 * 함수명 	: _setScreenInfo (내부함수)
	 * 함수설명	: window 창 설정 및 스크린 정보 저장 (내부함수)
	 * 				- window 창 : minimize, maximize, close (팝업화면에 적용됨)
	 * 				- 스크린 정보 저장 (싱글, 듀얼 모니터)
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _setScreenInfo() {
		try {
			// 팝업창 버튼 제어
			if (window.name != '') {
				window.wbrowser.setControlBoxButton('minimize', false);
				window.wbrowser.setControlBoxButton('maximize', false);
				window.wbrowser.setControlBoxButton('close', false);
			}

			window.wbrowser.getScreenInfo().then(function (info) {
				gcm.SCREEN_INFO.count 	= info.length;
				gcm.SCREEN_INFO.screen	= [];

				for (var i = 0 ; i < info.length ; i ++) {

					gcm.SCREEN_INFO.screen.push({
						top		: info[i].WorkingArea.Top,
						left	: info[i].WorkingArea.Left,
						height	: info[i].WorkingArea.Height,
						width	: info[i].WorkingArea.Width,
					});
				}
			});
		} catch(ex) {
			console.log('전용 브라우져 버전이 맞지 않음 - 최신 버전으로 설치해 주십시오.');
		}
	}


	/**
	 * 함수명 	: _setPopupActive
	 * 함수설명	: 하위 브라우져 모달 팝업 창 활성화 처리
	 * 				- 하위 브라우져 모달 팝업 창 활성화 : window focus 이벤트
	 * 				- 웹스퀘어 모달 팝업 창 활성화 이벤트 끄기
	 *                : 엔진에서는 하위 모달 창 만 활성화 시키기 때문에 팝업, 팝업 ... 인 경우 모든 하위 팝업창을 활성화 시키지 못함 
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _setPopupActive() {

		// 웹스퀘어 모달 팝업 창 활성화 이벤트 끄기
		com.comp.addHtmlEvent(document, 'click', function(e) {

			if (window.name == '' && e.target.id == '_modal') {
				//console.log({ev : 'click', in : e});
				com.win.stopEvent(e);
			}
		}, true);

		// 웹스퀘어 모달 팝업 창 활성화 이벤트 끄기
		com.comp.addHtmlEvent(document, 'dblclick', function(e) {
			if (window.name == '' && e.target.id == '_modal') {
				//console.log({ev : 'dblclick', in : e});
				com.win.stopEvent(e);
			}
		}, true);

		// 하위 브라우져 모달 팝업 창 활성화 처리
		com.comp.addHtmlEvent(window, 'focus', function(e) {
			if (e.target == window) {
				setTimeout(function() {
					mf.scope.com.win.setPopupActive();
				}, 150);
			}	
		}, true);
	}

};


