/**
 * 외부 솔루션 데이터 연계 (iFrame)
 *  - 외부 솔루션 연계 처리는 window postMessage를 이용함
 *
 * @author Inswave Systems
 * @class postmessage
 * @namespace gcm.postmessage
 */
// =============================================================================
gcm.postmessage = {};


/**
 * 함수명 	: gcm.postmessage.init
 * 함수설명	: window postMessage 리스너를 설정
 * 				- 
 * 파라미터	: N/A
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.postmessage.init = function() {

	//==========================================================================
	// oz 리포트 프린트 출력 후 메시지 이벤트
	//==========================================================================
	window.addEventListener('message', function(e) {

		console.log({message : e});

		if (e.data.system) {
			// OZ 리포트 및 PDF 솔루션 메시지 연계
			_systemMessage(e);
		} else {
			// 개발화면에서 postMessage 사용할 경우 처리
			_pageMessage(e);
		}
    });


	/**
	 * 함수명 	: _systemMessage
	 * 함수설명	: OZ, PDF 솔루션 메시지 처리 (내부함수)
	 * 				- 메시지 수신 후 등록된 콜백함수 호출
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _systemMessage(e) {
		var system		= e.data.system;
		var key			= e.data.key;
		var name 		= e.data.name;
		var data		= e.data.data;
		var isDelete	= e.data.isDelete;
		var winObj		= (e.data.pageType == 'iframe') ? window : opener;
		var callbackFn	= winObj.gcm.CB_FUNCTION_SYSTEM[system][key].callbackFn;

		try {
			if (system == 'oz') {

				if (name == 'install') {
					// OZ 뷰어 설치 시 Modal 창 닫기
					WebSquare.layer.hideModal();
				} else if (name == 'close') {
					// ESC 키 입력 시 닫기 실행 (팝업창)
					window[data.closeButtonId].trigger('click');

				} else if (name == 'print') {
					// 인쇄 완료 시 콜백
					if (callbackFn.print) callbackFn.print(data.code);

				} else if (name == 'save') {
					// 내보내기 완료 시 콜백
					if (callbackFn.save) callbackFn.save(data.code, data.filepath);

				} else if (name == 'error') {
					// 에러 시 콜백
					if (callbackFn.error) callbackFn.error(data.code, data.message);

				} else if (name == 'exit'){
					// 종료 시 콜백
					WebSquare.layer.hideModal();
					if (callbackFn.exit) callbackFn.exit();

				} 
			} else if (system == 'ezpdf') {

				var isDelete	= false;

				if (name == 'close') {
					// ESC 키 입력 시 닫기 실행 (팝업창)
					window[data.closeButtonId].trigger('click');

				} else if (name == 'sign') {


					// 인쇄 완료 시 콜백
					if (callbackFn.sign) callbackFn.sign(data);

				} else if (name == 'bm') {

					// 음영화 저장완료시 콜백
					if (callbackFn.bm) callbackFn.bm(data);

				} else if (name == 'error') {
					if (callbackFn.error) callbackFn.error(data);

				} else if (name == 'open') {
					// 주석view 오픈 시 콜백함수
					if (callbackFn.open) callbackFn.open(data);

				} else if (name == 'setScale' || name == 'getScale' || name == 'getScaleR' || name == 'getCPage' || name == 'getTPage' || name == 'bmLength') {
					// pdf request message to return message
					if (callbackFn) callbackFn(data);
				} else if (name == 'callMsgcd') {
					if (callbackFn) callbackFn(data);
				} else if (name == 'bmUpdate') {

					// 음영화 추가시 콜백
					if (callbackFn.bmUpdate) callbackFn.bmUpdate(data);

				} else if (name == "setkeyCallback"){

					if (callbackFn) callbackFn(data);
				} else if (name == "setScaleChangedCallback"){

					if (callbackFn) callbackFn(data);
				} else if (name == "setPageChangedCallback"){

					if (callbackFn) callbackFn(data);
				}

			}
		} catch(ex) {
			console.log(ex);
		}

		//===========================================================================	
		// 콜백 후 함수 삭제
		//===========================================================================
		if (isDelete) winObj.gcm.postmessage.callbackInfo(system, 'DELETE', key);
	}


	/**
	 * 함수명 	: _pageMessage
	 * 함수설명	: 기타 솔루션 화면연동 시 메시지 처리 (내부함수)
	 * 				- 메시지 수신 후 등록된 콜백함수 호출
	 * 파라미터	: N/A
	 * 리턴		: N/A
	 * 작성일 	: 2022.09.01
	 * 작성자 	: Inswave Systems
	 */
	function _pageMessage(e) {

		var pageType 	= e.data.pageType;		// iframe, popup
		var scopeId		= e.data.scopeId;		// scope id
		var compId		= e.data.compId;
		var funcName	= e.data.funcName;		// 실행할 함수명
		var funcParam	= e.data.funcParam;
		var execFn		= null;

		try {
			if (com.util.isNotEmpty(scopeId)) {
				execFn		= WebSquare.util.getGlobalFunction(funcName, scopeId);
			} else if (com.util.isNotEmpty(compId)) {
				var scopeId	= $p.getComponentById("lbl_sys_link_smaple").getScope().id;

				execFn		= WebSquare.util.getGlobalFunction(funcName, scopeId);
			}

			if (com.util.isFunction(execFn) == false) return;

			execFn(funcParam);
		} catch (ex) {
			console.log(ex);
		}
	}
};



/**
 * 함수명 	: gcm.postmessage.send
 * 함수설명	: 기타 솔루션에 메시지를 전송한다.
 * 파라미터	: N/A
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.postmessage.send = function(target, message) {
	target.postMessage(message, '*');
};



/**
 * 함수명 	: gcm.postmessage.callbackInfo
 * 함수설명	: 솔루션에서 전송한 메시지에 대한 콜백함수 실행/삭제 처리
 * 파라미터	: N/A
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.postmessage.callbackInfo	= function(system, type, key, info) {

	console.log({method : 'gcm.postmessage.callbackInfo'});

	var callbackInfo	= gcm.CB_FUNCTION_SYSTEM[system];

	if (!callbackInfo) return;

	// =============================================================================
	// 콜백 정보 추가 / 삭제
	// =============================================================================
	if (type == 'INSERT') {
		callbackInfo[key]	= info;
	} else if (type == 'DELETE'){
		delete callbackInfo[key];
	}

	// =============================================================================
	// 종료된 OZ, PDF 뷰어 메시지 콜백 정보 삭제
	// =============================================================================
	for ( var sysItem in gcm.CB_FUNCTION_SYSTEM) {

		var sysCallbackInfo	= gcm.CB_FUNCTION_SYSTEM[sysItem];

		for (var item in sysCallbackInfo) {

			var viewerType	= sysCallbackInfo[item].viewerType;
			var viewerId	= sysCallbackInfo[item].viewerId;

			if (viewerType == 'popup') {
				// 팝업 창 존재 여부 체크
				if (com.util.isEmpty(gcm.popup.getW2popup(viewerId))) {
					delete sysCallbackInfo[item];
				}
			} else if (viewerType == 'wframe') {
				if (com.util.isEmpty(window[viewerId])) {
					delete sysCallbackInfo[item];
				}
			}
		}
	}
}



