/**
 * 함수명 	: gcm.win.stopEvent
 * 함수설명	: 이벤트 버블링, 캡처링을 중지 한다.
 * 파라미터	: e : 이벤트 객체
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.win.stopEvent = function(e) {

	try {
		if (com.util.isEmpty(e)) {
			window.event.preventDefault();
			window.event.stopPropagation();
		} else {
			e.preventDefault();
			e.stopPropagation();
		}
	} catch(ex) {
		return false;
	}
};


/**
 * 함수명 	: gcm.win.getMainWindow
 * 함수설명	: 메인 Window 창을 리턴한다.
 * 파라미터	: N/A
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.win.getMainWindow = function() {

	var mainWin	= window;
	for (var i = 0 ; i < 100 ; i ++) {
		if (com.util.isEmpty(mainWin.opener)) {
			return mainWin;
		} else {
			try {
				if (mainWin.opener.WebSquare) {
					mainWin	= mainWin.opener;
				} else {
					return mainWin;
				}
			} catch(ex) {
				return mainWin;
			}
		}
	}
	return null;
};



/**
 * 특정 메뉴를 오픈한다.
 * @date 2021.02.16
 * @param {String} menuNm 메뉴명 - 단위화면에서 해당 값으로 title을 설정한다.
 * @param {String} url 화면 파일 경로
 * @param {String} menuCode 메뉴코드 (윈도우 ID)
 * @param {Object} paramObj
 * @param {String} menuType 메뉴타입
 * @param {Boolean} closeable 닫기버튼 보여주기 여부
 * @author Inswave Systems
 * @example
 * gcm.win.openMenu("인사조회","/tmp/tmp01.xml","010001");
 */


/**
 * 함수명 	: gcm.win.openMenu
 * 함수설명	: 메뉴를 오픈한다.
 * 파라미터	: $p : scope의 $p객체
 * 				menuInfo : 오픈 메뉴정보
 * 				param : 메뉴오픈 시 전달할 파라미터
 * 				beforeCallbackFn : 메뉴 오픈 시 호출할 함수
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.win.openMenu = function($p, menuInfo, param, beforeCallbackFn) {

	if (gcm.SYS_ID == 'IM10') {
		gcm.win.openMenuIM10($p, menuInfo, param, beforeCallbackFn);
	} else if (gcm.SYS_ID == 'PM10') {
		gcm.win.openMenuPM10($p, menuInfo, param);
	} else if (gcm.SYS_ID == 'PM20') {
		gcm.win.openMenuPM20($p, menuInfo, param);
	} else if (gcm.SYS_ID == 'SM30') {
		gcm.win.openMenuSM30($p, menuInfo, param);
	} else if (gcm.SYS_ID == 'PM60') {
		gcm.win.openMenuPM60($p, menuInfo, param);
	}
};


/**
 * 함수명 	: gcm.win.openMenuIM10
 * 함수설명	: 메뉴를 오픈한다. (IM10용)
 * 파라미터	: $p : scope의 $p객체
 * 				menuInfo : 오픈 메뉴정보
 * 				param : 메뉴오픈 시 전달할 파라미터
 * 				closable : 닫기 가능 여부 (true)
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.win.openMenuIM10 = function($p, menuInfo, param, beforeCallbackFn) {

	// 메뉴를 새창으로 띄운다. (window 오픈 : 사용안함)
    if (menuInfo.file_path == "/") {
        var url = document.location.href + "/";
        window.open(url, "", "width=1200, height=700, left=450, top=100");
    } else {

    	//=========================================================================
    	// 오픈할 정보 설정
    	//	- 메인 windowContainer 컴포먼트
    	//	- 전송 파라미터 설정 (메뉴 + 파라미터)
    	//	- URL 정보
    	//=========================================================================
    	var winObj		= $p.top().wdc_main;
    	var mainUrl		= '/ui/im10/com/include/Im10ComIncludeContentMain.xml';

    	menuInfo.url	= gcm.CONTEXT_PATH  + menuInfo.file_path;
    	menuInfo.sys_cd = (menuInfo.sys_cd) ? menuInfo.sys_cd : '';
        var dataObject	= {
        		type : 'json', 
        		name : 'paramData',
        		data : $.extend(menuInfo, (com.util.isNotEmpty(param)) ? param : {})
        };

        var menuName 	= menuInfo.scrn_name;

        if (menuName == "HOME") {
        	menuName 	= menuInfo.scrn_name;
        	//mainUrl		= menuInfo.file_path;
        } else {
        	menuName 	= '<span class="win_header ' + menuInfo.sys_cd + '">' + menuInfo.scrn_name + '</span><a class="btn_close"></a><div class="w2windowContainer_nameLayer_close"></div>';
        }

        //=========================================================================
        // 메뉴 열기 
        //	- menuInfo.grp_scrn_seq 열린 창 확인 
        //		- 없음 : New, 있음 : 포커스 이동
        //=========================================================================
        var tarWinObj	= winObj.getFrame(menuInfo.grp_scrn_seq, true);

        if (com.util.isEmpty(tarWinObj)) {
    		var options = {
                title 			: menuInfo.scrn_name,
                src 			: mainUrl,
                nameLayerHTML 	: menuName,
                windowTitle 	: menuInfo.scrn_name,
                windowId 		: menuInfo.grp_scrn_seq,
                openAction 		: "existWindow",
                frameMode 		: "wframe",
                fixed 			: false,
                closeAction 	: function(title) {
                	if (title === "HOME") {
                        return false;
                    } else {
                        return true;
                    }
                },
                dataObject : dataObject
            }

    		// windowContainer컴포넌트에 창 새로 추가
            winObj.createWindow(options);

    		_setWindowNameLayer();

        } else {
        	//=======================================================================
        	// 동일한 화면일 경우 새로 추가하지 않는다.
        	//	- menuInfo.reloadYn : 새로고침 여부
        	//		- Y : 새로고침, N : 포커스 이동
        	//=======================================================================
        	var tempUniqueId	= winObj.getUniqueIdByWindowId(menuInfo.grp_scrn_seq);
        	var uniqueId		= (com.util.isArray(tempUniqueId)) ? tempUniqueId[0] : tempUniqueId;
        	var subWinObj		= winObj.getWinInfoObj(uniqueId);

        	// 새로고침 여부 체크
        	var isReload	= (menuInfo.reloadYn == 'Y') ? true : false;

        	if (!isReload && tarWinObj._dataObject.data.scrn_id != menuInfo.scrn_id) {
        		isReload	= true;
        	}

        	//===============================================================================
        	// 메뉴 변경 전 beforeCallbackFn 함수를 호출하여 업무에서 사전 체크 함.
        	//	- beforeCallbackFn 함수는 반드시 true / false를 리턴해야 된다.
        	//	   > true : 메뉴 변경 실행, false : 메뉴 변경 안함
        	//	- beforeCallbackFn 함수는 일반함수, promise 함수 모두를 지원함.
        	//===============================================================================
        	var tarFrameObj				= tarWinObj.getWindow().wfm_main.getWindow();
        	var beforeCallBackResult	= null;

        	if (beforeCallbackFn) {
        		beforeCallBackResult	= beforeCallbackFn(tarFrameObj, isReload);

        		if ( beforeCallBackResult instanceof Promise) {
	        		beforeCallBackResult.then(function(data) {

	        			if (data == true) {
		        			_reloadWindow(isReload);
		        			_setWindowNameLayer();
	        			} else {
	        			}
	        		});
	        	} else {
	        		if (beforeCallBackResult) {
	        			_reloadWindow(isReload);
		        		_setWindowNameLayer();
	        		}
	        	}
        	} else {
        		_reloadWindow(isReload);
        		_setWindowNameLayer();
        	}
	    }

        //=======================================================================
        // 컨텐츠 클릭 시 메뉴 windowContainer 클릭 이벤트가 발생하여 버블링 제거
    	//=======================================================================
        gcm.win.stopEvent();
    }


    /**
     * 함수명 	: _reloadWindow
     * 함수설명	: window 컨테이너를 새로운 메뉴로 새로고침 한다. (내부함수)
     * 파라미터	: isReload : 새로고침 여부
     * 리턴		: N/A
     * 작성일 	: 2022.09.01
     * 작성자 	: Inswave Systems
     */
    function _reloadWindow(isReload) {

    	if (isReload) {

    		subWinObj.title			= menuInfo.scrn_name;
        	subWinObj.toolTip		= menuInfo.scrn_name;
        	subWinObj.windowTitle	= menuInfo.scrn_name;
        	subWinObj.nameLayerHTML = menuName;

        	winObj.createNameLayer();

        	winObj.nowWindow	= uniqueId;
        	winObj.selectWindow();

        	tarWinObj.setDataObject(dataObject);
        	tarWinObj.setSrc(mainUrl, {dataObject : dataObject});
    	}

    	winObj.nowWindow	= uniqueId;
    	winObj.selectWindow();
    }


    /**
     * 함수명 	: _setWindowNameLayer
     * 함수설명	: window 컨테이너를 nameLayer를 설정한다. (내부함수)
     * 파라미터	: N/A
     * 리턴		: N/A
     * 작성일 	: 2022.09.01
     * 작성자 	: Inswave Systems
     */
    function _setWindowNameLayer() {
    	//=======================================================================
        // subWindow 창 Close HTML 추가 (엔진에서 nameLayer 사용 시 비정상 동작으로 HTML 작업)
        //=======================================================================
    	var toolBarObj	= $(winObj.dom.mf_wdc_main_toolbar);
    	for (var i = 1 ; i < winObj.windows.length ; i ++) {

    		var subWinId	= winObj.windows[i].id;
    		var nameLayer	= toolBarObj.find('.w2windowContainer_nameLayer').filter('[refid=' + subWinId + ']');
    		var nameClose	= nameLayer.find('.w2windowContainer_nameLayer_close');
    		nameClose.attr('refid', subWinId);

    		winObj.windows[i].nameLayerHTML	= nameLayer.html();
    	}

    	setTimeout(function() {
    		winObj.selectWindow();
    	}, 100);
    }
};

/**
 * 함수명 	: gcm.win.openMenuPM10
