/**
 * 함수명 	: gcm.data.getWasMessageURL
 * 함수설명	: 메시지 조회 서비스 URL을 조회한다. (WAS별로 URL이 틀림)
 * 				- 메시지 프로퍼티 CD에 시스템 코드가 있음 (앞4자리)
 * 				- gcm.SYS_MESSAGE_URL에 등록되어 있는 경우 gcm.SYS_MESSAGE_URL에서 조회 후 리턴
 * 				- gcm.SYS_MESSAGE_URL에 미등록되어 있는 경우 gcm.data.getWasMessageURLValue 서비스를 호출 후 리턴된 URL을 gcm.SYS_MESSAGE_URL에 저장하고 URL 리턴
 * 파라미터	: wasSysId : WAS 시스템 코드
 * 리턴		: 메시지 조회 서비스 URL
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.data.getWasMessageURL = function(wasSysId) {

	var webSysId	= gcm.SYS_ID.toLowerCase();

	if (webSysId == 'em40' || webSysId == 'pm20' || webSysId == 'pm60' || webSysId == 'sm30') {
		return gcm.SYS_MESSAGE_URL['egov'];
	}

	if (gcm.SYS_MESSAGE_URL[wasSysId]) {
		return gcm.SYS_MESSAGE_URL[wasSysId];
	} else {
		var propertyCd	= webSysId + '.websquare.message.' + wasSysId + '.url';

		var url	= gcm.data.getWasMessageURLValue(wasSysId, propertyCd);

		gcm.SYS_MESSAGE_URL[wasSysId]	= url;

		return url;
	}
};


