 * 작성자 	: Inswave Systems
 */
gcm.data.clearSessionStorage = function () {

	var mainWin	= gcm.win.getMainWindow();
	mainWin.sessionStorage.clear();
};


/**
 * 함수명 	: gcm.data.setSessionStorage
 * 함수설명	: 세션 스토리지를 저장한다.
 * 				- JSON 데이터는 문자열로 변환하여 저장
 * 파라미터	: key :저장 키
 * 			  value : 값
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.data.setSessionStorage = function (key, value) {

	var value	= (com.util.isJSON(value)) ? JSON.stringify(value) : value;

	var mainWin	= gcm.win.getMainWindow();
	mainWin.sessionStorage.setItem(key, value);
};


/**
 * 함수명 	: gcm.data.getSessionStorage
 * 함수설명	: 세션 스토리지를 조회한다.
 * 파라미터	: key : 조회 키
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.data.getSessionStorage = function (key) {

	var mainWin	= gcm.win.getMainWindow();
	var value	= mainWin.sessionStorage.getItem(key);

	return com.util.stringToJSON(value);
};


/**
 * 함수명 	: gcm.data.removeLocalStorage
 * 함수설명	: 로컬 스토리지를 삭제한다.
 * 파라미터	: key : 삭제 키
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.data.removeLocalStorage = function (key) {
	if (com.util.isNotEmpty(key)) {
		var mainWin	= gcm.win.getMainWindow();
