/**
 * 함수명 	: gcm.data.setLocalStorage
 * 함수설명	: 로컬 스토리지를 저장한다.
 * 파라미터	: key : 저장 키
 * 			  value : 값
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.data.setLocalStorage = function (key, value) {
	if (com.util.isEmpty(key) || com.util.isEmpty(value)) {
		return;
	}

	try {
		if (com.util.isJSON(value)) {
			value = JSON.stringify(value);
	    }
    } catch (ex) {
        console.error(ex);
        return;
    }

    var mainWin	= gcm.win.getMainWindow();
    mainWin.WebSquare.localStorage.setItem(key, value);
};


/**
 * 함수명 	: gcm.data.getLocalStorage
 * 함수설명	: 로컬 스토리지를 조회한다.
 * 파라미터	: key : 조회 키
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.data.getLocalStorage = function (key) {
	if (com.util.isEmpty(key)) {
		return null;
	}

    try {
    	var mainWin	= gcm.win.getMainWindow();
    	var rtnVal = mainWin.WebSquare.localStorage.getItem(key);
        if (com.util.isJSON(rtnVal)) {
        	rtnVal = com.util.stringToJSON(rtnVal);
        }
    } catch (ex) {
        console.error(ex);
        return "";
    }

    return rtnVal;
};


