/**
 * 함수명 	: gcm.util._getUserAgent
 * 함수설명	: 웹 브라우저 종류를 반환한다.
 * 파라미터	: N/A
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.util._getUserAgent = function() {
    try {
        var agt = navigator.userAgent.toLowerCase();
        if (agt.indexOf("edg") != -1) {
            return 'Edge';
        } else if (agt.indexOf("chrome") != -1) {
            return 'Chrome';
        } else if (agt.indexOf("opera") != -1) {
            return 'Opera';
        } else if (agt.indexOf("staroffice") != -1) {
            return 'Star Office';
        } else if (agt.indexOf("webtv") != -1) {
            return 'WebTV';
        } else if (agt.indexOf("beonex") != -1) {
            return 'Beonex';
        } else if (agt.indexOf("chimera") != -1) {
            return 'Chimera';
        } else if (agt.indexOf("netpositive") != -1) {
            return 'NetPositive';
        } else if (agt.indexOf("phoenix") != -1) {
            return 'Phoenix';
        } else if (agt.indexOf("firefox") != -1) {
            return 'Firefox';
        } else if (agt.indexOf("safari") != -1) {
            return 'Safari';
        } else if (agt.indexOf("skipstone") != -1) {
            return 'SkipStone';
        } else if (agt.indexOf("msie") != -1 || agt.indexOf("trident") != -1) {
            return 'msie';
        } else if (agt.indexOf("netscape") != -1) {
            return 'Netscape';
        } else if (agt.indexOf("mozilla/5.0") != -1) {
            return 'Mozilla';
        } else {
            return '';
        }
    } catch (ex) {
        return '';
    }
};


/**
 * 함수명 	: gcm.util._getParameter
 * 함수설명	: GET 방식으로 전달한 파라미터를 조회한다.
 * 파라미터	: param : 조회할 파라미터
 * 			  url : URL
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.util._getParameter = function(param, url) {
    if (com.util.isEmpty(url)) {
        url = unescape(location.href);
    }
    var paramArr = (url.substring(url.indexOf("?")+1,url.length)).split("&");
    var value = "";

    for(var i = 0 ; i < paramArr.length ; i++) {
        var temp = paramArr[i].split("=");

        if(temp[0].toUpperCase() == param.toUpperCase()) {
            value = paramArr[i].split("=")[1];
            break;
        }
    }

    return value;
};


