/**
 * 세션 관련 모듈 (세션 정보는 서비스를 통해 조회해야 됨.)
 *
 * @author Inswave Systems
 * @class session
 * @namespace gcm.session
 */
// =============================================================================


gcm.session	= {};

gcm.session.getCrptedUrl	= function(url) {

	var crpId = gcm.data.getLocalStorage("CRYPTED_ID__");
	var userId = gcm.data.getLocalStorage("USER_ID__");
	var isNmbr = gcm.data.getLocalStorage("IS_NMBR_LOGIN__");
	var wgearIp = gcm.data.getLocalStorage("WGEAR_IP__");

	if (com.util.isNotEmpty(userId)) {
		userId	= encodeURIComponent(userId);
	}

	if(url.indexOf("CRYPTED_ID__") == -1) {
		if (com.util.isNotEmpty(crpId)) {
			url += "?CRYPTED_ID__=" + crpId + "&USER_ID__=" + userId;
		}
	}

	// L4에 의해 CLIENT PC IP 가 전달되지 않아 WGEAR를 통해 강제로 전달함
	if (gcm.SYS_ID == 'IM10') {
		if(url.indexOf("WGEAR_IP__") == -1) {
			if(url.indexOf("CRYPTED_ID__") == -1) {
				url += "?WGEAR_IP__=" + wgearIp;
			} else {
				url += "&WGEAR_IP__=" + wgearIp;
			}
		}
	}

	if (gcm.SYS_ID == 'PM10') {
		if(url.indexOf("CRYPTED_ID__") == -1) {
			url += "?IS_NMBR_LOGIN__=" + isNmbr;
		} else {
			url += "&IS_NMBR_LOGIN__=" + isNmbr;
		}
	}

	return url;
};


