gcm.session.getMenu = function(id) {

	if (com.util.isNotEmpty(id)) {
		var filterData	= gcm.session.menu.filter(function(item) {
			return item.menu_seq == id;
		});

		if (filterData.length != 0) {
			return filterData[0];
		}
	} else {
		return gcm.session.menu;
	}
};


/**
 * 함수명 	: gcm.session.findMenu
 * 함수설명	: 메뉴정보를 조회한다.
 * 파라미터	: info : 조회 정보
 * 리턴		: 메뉴정보
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.session.findMenu = function(info) {

	if (com.util.isNotEmpty(info)) {
		var filterData	= gcm.session.menu.filter(function(item) {
			return item[info.colId] == info.val;
		});

		if (filterData.length != 0) {
			return filterData[0];
		}
	} else {
		return null;
	}
};


/**
 * 함수명 	: gcm.session.isLogin
 * 함수설명	: 로그인 여부를 체크한다.
 * 파라미터	: reqUi : URL
 * 리턴		: 여부 (true / false)
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.session.isLogin = function(reqUi) {

	var deferred = $.Deferred();
    var reqData = {
		"req_ui" : reqUi
	};
    var isLoginOption = {
    	"id" 			: "sbm_isLoginCheck",
    	"action" 		: "/egov/EgovNrsSessionBaseCtrl/isLogin.do",
    	"method" 		: "post",
    	"mediatype" 	: "application/json",
    	"mode" 			: "synchronous",
    	"processMsg" 	: '$blank',
    	"submitDoneHandler" : function(e) {
    		deferred.resolve(e);
    	},
    	"submitErrorHandler" : function(e) {
    		deferred.reject(e);
    	}
    };
    var sbmObj	= com.sbm.create(isLoginOption);

    $p.executeSubmission(sbmObj, reqData);

    return deferred.promise();
};



/**
 * 함수명 	: gcm.session.initSystem
 * 함수설명	: 각 시스템별 최초 서비스를 조회하여 세션을 유지한다.
 * 파라미터	: N/A
 * 리턴		: N/A
 * 작성일 	: 2022.09.01
 * 작성자 	: Inswave Systems
 */
gcm.session.initSystem = function() {

	if (gcm.SYS_ID == 'IM10') {
		_send('Ic10');

		_send('Ib10');
		_send('Ic20');
		_send('Im20');
		_send('Im30');
		_send('Im50');
		_send('Im60');
		_send('Ir10');
		_send('Is10');
		_send('Sm60');

	} else if (gcm.SYS_ID == 'PM10') {
		_send('Pb10');
		_send('Pc10');
		_send('Pc20');
		_send('Pc30');
		_send('Pd10');
		_send('Pd20');
		_send('Pm10');
		_send('Pm30');
		_send('Pm40');
		_send('Pm50');
		_send('Pr10');
		_send('Pr20');
		_send('Ps10');
		_send('Ps20');

	} else {
		return;
	}

	function _send(wasId) {

		var action 	= gcm.session.getCrptedUrl('/biz/' + wasId + 'ComCodeIndvCtrl/touchSso.do');

		var ajaxOption = {
			action		: action,
	    	mode 		: 'asynchronous',
	    	mediatype  	: 'text/json',
	    	method		: 'POST',
	    	timeout		: 100,
	    };
		$p.ajax(ajaxOption);
	}
};


// 오케스트라 결함등록 노출 FLAG
gcm.META_FLAG	= 'none';



//=============================================================================
/**
 * 기타 전역 이벤트 정의 및 함수
 *
 * @author Inswave Systems
 * @class session
 * @namespace gcm.session
 */
// =============================================================================
(function(factory, undefined) {

	//==========================================================================
	// Window 창 닫기 시 오픈한 팝업 창 닫기
	//==========================================================================
	$(window).bind('unload', function(e) {

		try {
			if (com.util.isEmpty(window.name)) {
				com.win.closePopupAll();
			} else {
				var searchOptions= {
					id 		: window.name + '_wframe_mf',
					type 	: 'CHILD'
				};
				var popList	= com.win.searchPopup(searchOptions, 'POPUP');

				com.win.closePopupList(popList);
			}
		} catch(e) {
			return '';
		}
		return '';
	});


	//==========================================================================
	// 결함등록 단축키 노출 이벤트
	//==========================================================================
	$(document).bind('keyup', function(e) {

		if (e.shiftKey && e.key == 'F9') {
			if (gcm.META_FLAG == 'none') {
				$('.META_INFO').show();
				gcm.META_FLAG	= 'block';
			} else {
				$('.META_INFO').hide();
				gcm.META_FLAG	= 'none';
			}

		}
	});
})();


