function returnData(vData) {
	console.log('frame에서 받음');

	var uuid = WebSquare.excelUploadUUID;

	if (uuid.indexOf('__UDC_EXCEL_UPLOAD__') != -1) {

		WebSquare.util.getComponentById(uuid.replace('__UDC_EXCEL_UPLOAD__', '')).uploadExcelData(vData);
