}

//=========================================================================================
//가상 키패드 입력값의 포맷을 지정 (PM10, PM20)
//  - 주민번호 (ssn) : 키패드 선택 시 해당 컴포넌트 onkeydown 이벤트 호출
//=========================================================================================
if (gcm.SYS_ID == 'PM10' || gcm.SYS_ID == 'PM20' || gcm.SYS_ID == 'ZI01') {

	var npPfsExtension = new function() {

		// $element : 입력양식,
		// isInput : (true : 데이터 포맷 지정 , false : 데이터 포맷 삭제)
		this.formatter = function($element, isInput) {
			var str 	= $element.val();
			var type 	= $element.attr("nppfs-formatter-type");

			try {
				var compId	= $element.attr('id');
				var compObj	= window[compId];

				if (isInput == true) {
					if (type == 'keydown') {
						WebSquare.event.fireEvent(compObj, "onkeydown");
					}
				}
				return compObj.getValue();
			} catch (ex) {
				console.log(ex);
				return str;
			}
		}
	};
}
